PHD = {p[0]: p for p in PH}
def mean_groups():
    g = {}
    for p, m, l in PH: g.setdefault(m, []).append(p)
    return g
MG = mean_groups()
def f_ph_mean(T, rng, lv):
    pool = [p for p in PH if p[2] == lv] if lv < 3 or True else PH
    p, m, l = rng.choice(pool)
    others = [q for q in PH if q[1] != m]
    ds = []
    seen = {m}
    for q in rng.sample(others, len(others)):
        if q[1] in seen: continue
        seen.add(q[1]); ds.append(q)
        if len(ds) == (4 if lv == 3 else 3): break
    wr = [(q[1], f'це значення виразу «{q[0]}»') for q in ds]
    trap = {1: 'частина виразів уживається у переносному значенні, тому за окремими словами значення не вгадаєш', 2: 'буквальне прочитання виразу веде до хибного значення', 3: 'вираз закріпився у мові як цілісна одиниця, його значення не випливає зі значень окремих слів'}[lv]
    return T.add(lv, f'Що означає фразеологізм «{p}»?', m, wr, trap, f'«{p}» = {m}')
def f_ph_rev(T, rng, lv):
    pool = [p for p in PH if p[2] == lv]
    p, m, l = rng.choice(pool)
    others = [q for q in PH if q[1] != m]
    ds = []; seen = {m}
    for q in rng.sample(others, len(others)):
        if q[1] in seen: continue
        seen.add(q[1]); ds.append(q)
        if len(ds) == 3: break
    wr = [(q[0], f'означає «{q[1]}»') for q in ds]
    return T.add(lv, f'Який фразеологізм має значення «{m}»?', p, wr, 'шукай вираз за значенням, а не за окремими словами', f'«{p}» означає: {m}')
def f_ph_syn(T, rng, lv):
    groups = [(m, ps) for m, ps in MG.items() if len(ps) >= 2]
    m, ps = rng.choice(groups)
    a, b = rng.sample(ps, 2)
    others = [q for q in PH if q[1] != m]
    ds = rng.sample(others, 3)
    wr = [(q[0], f'означає «{q[1]}», а не «{m}»') for q in ds]
    return T.add(lv, f'Укажіть фразеологізм, синонімічний до виразу «{a}».', b, wr, 'синонімічні фразеологізми мають спільне значення, але різну образність', f'обидва вирази означають «{m}»')

# ---- синоніми й антоніми ----
SYN = [('adj', ['відважний', 'сміливий', 'хоробрий', 'мужній', 'безстрашний']), ('adj', ['гарний', 'красивий', 'вродливий', 'мальовничий']), ('adj', ['швидкий', 'прудкий', 'жвавий', 'стрімкий']),
       ('adj', ['сумний', 'невеселий', 'журливий', 'смутний']), ('adj', ['втомлений', 'знесилений', 'виснажений', 'стомлений']), ('adj', ['величезний', 'гігантський', 'велетенський', 'неозорий']),
       ('noun', ['розмова', 'бесіда', 'діалог']), ('noun', ['вчитель', 'педагог', 'наставник']), ('noun', ['ворог', 'недруг', 'супротивник']), ('noun', ['радість', 'втіха', 'щастя']),
       ('noun', ['дорога', 'шлях', 'путь']), ('noun', ['мрія', 'сподівання', 'омріяне']), ('verb', ['працювати', 'трудитися', 'трудиться'][:2]), ('verb', ['говорити', 'мовити', 'казати', 'розмовляти']),
       ('verb', ['бачити', 'дивитися', 'споглядати']), ('verb', ['думати', 'міркувати', 'роздумувати'])]
SYN = [x for x in SYN if len(x[1]) >= 3]
ANT = [('adj', 'добрий', 'злий'), ('adj', 'світлий', 'темний'), ('adj', 'високий', 'низький'), ('adj', 'швидкий', 'повільний'), ('noun', 'радість', 'смуток'), ('noun', 'правда', 'неправда'), ('noun', 'початок', 'кінець'),
       ('adj', 'сміливий', 'боязкий'), ('adj', 'багатий', 'бідний'), ('adj', 'чистий', 'брудний'), ('adv', 'далеко', 'близько'), ('adj', 'молодий', 'старий'), ('noun', 'мир', 'війна'), ('noun', 'тепло', 'холод'),
       ('adj', 'сильний', 'слабкий'), ('adv', 'вгору', 'вниз'), ('noun', 'день', 'ніч'), ('noun', 'друг', 'ворог')]
def f_syn(T, rng, lv):
    pos, s = rng.choice(SYN)
    w, c = rng.sample(s, 2)
    ant = [x for x in ANT if x[0] == pos and w in x[1:]]
    other_syn = [x for p, g in SYN if p == pos and g is not s for x in g]
    if len(other_syn) < 2: return False
    wr = []
    if ant and lv >= 2: wr.append(([y for y in ant[0][1:] if y != w][0], f'це антонім до «{w}»'))
    for x in rng.sample(other_syn, 3): wr.append((x, 'слово з іншого синонімічного ряду, значення відмінне'))
    return T.add(lv, f'Укажіть синонім до слова «{w}».', c, wr[:3], 'синонім — слово з близьким значенням, а не з протилежним', f'«{w}» і «{c}» близькі за значенням')
def f_ant(T, rng, lv):
    pos, a, b = rng.choice(ANT)
    if rng.random() < .5: a, b = b, a
    syn = [g for p, g in SYN if p == pos and a in g]
    pool = [x for p, y1, y2 in ANT if p == pos and a not in (y1, y2) for x in (y1, y2)]
    pool += [x for p, g in SYN if p == pos for x in g if x != a]
    pool = [x for x in pool if x != b]
    if len(pool) < 3: return False
    wr = []
    if syn: wr.append(([y for y in syn[0] if y != a][0], f'це синонім до «{a}»'))
    for x in rng.sample(pool, 3): wr.append((x, f'не має значення, протилежного до «{a}»'))
    return T.add(lv, f'Укажіть антонім до слова «{a}».', b, wr[:3], 'антонім має протилежне значення', f'«{a}» і «{b}» протилежні за значенням')

